const attachments = Array.from({ length: 12 }, (_, index) => {
  const documentIndex = index + 1;
  const sequence = String(documentIndex).padStart(2, '0');
  const fileName = `document-${sequence}.docx`;

  return {
    document_index: documentIndex,
    file_name: fileName,
    file_extension: 'docx',
    display_name: fileName,
    download_url: `https://REPLACE_ME/${fileName}`,
    publication_at: null,
    source_size: null,
  };
});

const tenderMeta = {
  source: 'manual_test',
  tender_id: 'manual-calibration-167-26-ZO',
  tender_number: null,
  tender_external_id: null,
  eid: null,

  title: null,
  max_price: null,
  currency: null,

  region: null,
  status: null,
  kind: null,
  type: null,
  placing_way: null,

  publication_at: null,
  receive_at: null,
  submission_start_at: null,
  submission_close_at: null,
  scoring_at: null,
  summing_up_at: null,
  updated_at_source: null,

  customers: [],
  primary_customer: null,

  platform: {
    name: null,
    url: null,
  },

  tender_url: null,

  prepayment: null,
  guarantee_application: null,
  guarantee_contract: null,
  guarantee_provision: null,

  okpd2: [],
  okpd: [],
  ktru: [],

  smp: null,
  multilot: null,
  is_changed: null,
  is_deleted: null,

  documents_count: attachments.length,
};

return [
  {
    json: {
      tender_meta: tenderMeta,
      attachments,
      raw_source: {
        source: 'manual_test',
        ingestion_type: 'manual_https_fixture',
        fixture_id: tenderMeta.tender_id,
        tender: {
          _id: tenderMeta.tender_id,
          attachments: attachments.map(attachment => ({
            realName: attachment.file_name,
            displayName: attachment.display_name,
            href: attachment.download_url,
            publicationDateTime: null,
            size: attachment.source_size,
          })),
        },
      },
    },
  },
];

const input = $json;
const tenderMeta = input.tender_meta;
const attachments = input.attachments;

if (!tenderMeta || typeof tenderMeta !== 'object' || Array.isArray(tenderMeta)) {
  throw new Error('[Calibration Fixture] tender_meta должен быть объектом');
}

if (tenderMeta.source !== 'manual_test') {
  throw new Error('[Calibration Fixture] tender_meta.source должен быть manual_test');
}

if (typeof tenderMeta.tender_id !== 'string' || !tenderMeta.tender_id.trim()) {
  throw new Error('[Calibration Fixture] tender_meta.tender_id отсутствует');
}

if (!Array.isArray(attachments)) {
  throw new Error('[Calibration Fixture] attachments должен быть массивом');
}

if (attachments.length !== 12) {
  throw new Error(
    `[Calibration Fixture] ожидалось 12 attachments, получено: ${attachments.length}`
  );
}

const allowedExtensions = new Set(['pdf', 'docx', 'xlsx']);
const documentIndexes = new Set();

attachments.forEach((attachment, index) => {
  const path = `attachments[${index}]`;

  if (!attachment || typeof attachment !== 'object' || Array.isArray(attachment)) {
    throw new Error(`[Calibration Fixture] ${path} должен быть объектом`);
  }

  if (!Number.isInteger(attachment.document_index) || attachment.document_index <= 0) {
    throw new Error(`[Calibration Fixture] ${path}.document_index должен быть positive integer`);
  }

  if (documentIndexes.has(attachment.document_index)) {
    throw new Error(
      `[Calibration Fixture] duplicate document_index: ${attachment.document_index}`
    );
  }
  documentIndexes.add(attachment.document_index);

  if (typeof attachment.file_name !== 'string' || !attachment.file_name.trim()) {
    throw new Error(`[Calibration Fixture] ${path}.file_name отсутствует`);
  }

  if (!allowedExtensions.has(attachment.file_extension)) {
    throw new Error(
      `[Calibration Fixture] ${path}.file_extension не поддерживается: ${attachment.file_extension}`
    );
  }

  if (typeof attachment.download_url !== 'string' || !attachment.download_url.trim()) {
    throw new Error(`[Calibration Fixture] ${path}.download_url отсутствует`);
  }
});

return {
  json: input,
};
